import json


def add_server(config_text, key, identifier):
    """Return config_text with a uvx server entry added under mcpServers.

    Every server and every other setting already in the file is kept. If a
    server is already configured under the same key, raise ValueError.
    """
    config = json.loads(config_text)
    servers = config.get("mcpServers", {})
    if key in servers:
        raise ValueError(f"a server named {key!r} is already configured")
    config = {"mcpServers": {key: {"command": "uvx", "args": [identifier]}}}
    return json.dumps(config, indent=2)

