import json


def add_server(config_text, key, identifier):
    """Return config_text with a uvx server entry added under mcpServers.

    Every server and every other setting already in the file is kept. If a
    server is already configured under the same key, raise ValueError.
    """
    config = json.loads(config_text)
    servers = config.get("mcpServers", {})
    if key in servers:
        raise ValueError(f"a server named {key!r} is already configured")
    servers[key] = {"command": "uvx", "args": [identifier]}
    config["mcpServers"] = servers
    return json.dumps(config, indent=2)

questions.tests:
import json

existing = json.dumps({
    "globalShortcut": "Ctrl+Space",
    "mcpServers": {
        "notes": {"command": "uvx", "args": ["notes-server"], "env": {"NOTES_DIR": "~/notes"}}
    }
})

out = add_server(existing, "orders", "orders-pg-server")
config = json.loads(out)  # 1. the result must still parse as JSON

# 2. nothing that was already in the file is lost
assert config.get("globalShortcut") == "Ctrl+Space", "a top-level setting was dropped"
assert "notes" in config.get("mcpServers", {}), "the server configured yesterday was dropped"
assert config["mcpServers"]["notes"] == {"command": "uvx", "args": ["notes-server"], "env": {"NOTES_DIR": "~/notes"}}, "an existing server's settings were changed"

# 3. the new entry launches the copied identifier with uvx, as a list of arguments
assert config["mcpServers"]["orders"] == {"command": "uvx", "args": ["orders-pg-server"]}, config["mcpServers"].get("orders")
assert "servers" not in config, "VS Code's key does not belong in an mcpServers file"

# 4. an empty file and a file without mcpServers both work
assert json.loads(add_server("{}", "a", "pkg-a")) == {"mcpServers": {"a": {"command": "uvx", "args": ["pkg-a"]}}}
two = json.loads(add_server(add_server("{}", "a", "pkg-a"), "b", "pkg-b"))
assert set(two["mcpServers"]) == {"a", "b"}, "adding a second server removed the first"

# 5. an existing key is refused, not overwritten
try:
    add_server(existing, "notes", "other-server")
except ValueError:
    pass
else:
    raise AssertionError("an existing server was silently replaced")
print("all tests passed")
